// ── Receiver ─────────────────────────────────────────────────────
class TextDocument {
  constructor(content = '') { this.content = content; }
  insert(text, pos)  { this.content = this.content.slice(0, pos) + text + this.content.slice(pos); }
  delete(pos, len)   { this.content = this.content.slice(0, pos) + this.content.slice(pos + len); }
  toString()         { return this.content; }
}

// ── Concrete Commands ────────────────────────────────────────────
class InsertCommand {
  constructor(doc, text, pos) {
    this._doc = doc; this._text = text; this._pos = pos;
  }
  execute() { this._doc.insert(this._text, this._pos); }
  undo()    { this._doc.delete(this._pos, this._text.length); }
}

class DeleteCommand {
  constructor(doc, pos, len) {
    this._doc = doc; this._pos = pos; this._len = len;
    this._deleted = '';         // saved for undo
  }
  execute() {
    this._deleted = this._doc.content.slice(this._pos, this._pos + this._len);
    this._doc.delete(this._pos, this._len);
  }
  undo() { this._doc.insert(this._deleted, this._pos); }
}

// ── Invoker with undo/redo stacks ────────────────────────────────
class CommandHistory {
  constructor() { this._undo = []; this._redo = []; }

  run(cmd) {
    cmd.execute();
    this._undo.push(cmd);
    this._redo = [];           // new action clears redo stack
  }

  undoLast() {
    const cmd = this._undo.pop();
    if (!cmd) return console.log('[History] Nothing to undo');
    cmd.undo();
    this._redo.push(cmd);
  }

  redoLast() {
    const cmd = this._redo.pop();
    if (!cmd) return console.log('[History] Nothing to redo');
    cmd.execute();
    this._undo.push(cmd);
  }
}

// ── Usage ────────────────────────────────────────────────────────
const doc     = new TextDocument('Hello World');
const history = new CommandHistory();

console.log(doc.toString()); // Hello World

history.run(new InsertCommand(doc, ', JS', 5));
console.log(doc.toString()); // Hello, JS World

history.run(new DeleteCommand(doc, 0, 6));
console.log(doc.toString()); // JS World

history.undoLast();
console.log(doc.toString()); // Hello, JS World

history.undoLast();
console.log(doc.toString()); // Hello World

history.redoLast();
console.log(doc.toString()); // Hello, JS World

// ── Command interface skeleton ───────────────────────────────────
class Command {
  execute() { throw new Error('execute() not implemented'); }
  undo()    { throw new Error('undo() not implemented'); }
}

// ── Task queue use-case (serializable Command) ───────────────────
class SendEmailCommand extends Command {
  constructor({ to, subject, body }) {
    super();
    this._to = to; this._subject = subject; this._body = body;
    this._sentId = null;
  }

  async execute() {
    // In production: call an email SDK
    this._sentId = `msg_${Date.now()}`;
    console.log(`[Email] Sent "${this._subject}" to ${this._to} — id: ${this._sentId}`);
  }

  async undo() {
    if (this._sentId) console.log(`[Email] Cancelling ${this._sentId} (if within window)`);
  }

  // Serializable for queuing
  toJSON() {
    return { type: 'SendEmail', to: this._to, subject: this._subject, body: this._body };
  }
}

// ── Simple task queue ────────────────────────────────────────────
class TaskQueue {
  constructor() { this._queue = []; }
  enqueue(cmd) { this._queue.push(cmd); }
  async flush() {
    while (this._queue.length) {
      const cmd = this._queue.shift();
      await cmd.execute();
    }
  }
}

const queue = new TaskQueue();
queue.enqueue(new SendEmailCommand({ to: 'a@b.com', subject: 'Welcome', body: 'Hi!' }));
queue.enqueue(new SendEmailCommand({ to: 'c@d.com', subject: 'Invoice', body: '$99' }));
queue.flush();
